'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var dlasr = require( './../lib' );

// Specify matrix meta data for A (M x N):
var shapeA = [ 3, 2 ];
var order = 'row-major';
var stridesA = shape2strides( shapeA, order );

// Plane rotation parameters:
var C = new Float64Array( [ 0.8, 0.7 ] );
var S = new Float64Array( [ 0.6, -0.7142857142857143 ] );

// The matrix A to be transformed:
var A = new Float64Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0 ] );

console.log( 'A (unmodified):', ndarray2array( A, shapeA, stridesA, 0, order ) );

// Apply the sequence of plane rotations in-place:
dlasr( order, 'left', 'variable', 'forward', shapeA[ 0 ], shapeA[ 1 ], C, S, A, stridesA[ 0 ] );

console.log( 'A (P * A):', ndarray2array( A, shapeA, stridesA, 0, order ) );

// Re-initialize arrays for the alternative interface:
C = new Float64Array( [ 0.8, 0.7 ] );
S = new Float64Array( [ 0.6, -0.7142857142857143 ] );
A = new Float64Array( [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0 ] );

// Re-initialize matrix meta data:
stridesA = shape2strides( shapeA, order );

// Apply the sequence of plane rotations in-place using ndarray interface:
dlasr.ndarray( 'left', 'variable', 'forward', shapeA[ 0 ], shapeA[ 1 ], C, 1, 0, S, 1, 0, A, stridesA[ 0 ], stridesA[ 1 ], 0 );

console.log( 'A (P * A) ndarray:', ndarray2array( A, shapeA, stridesA, 0, order ) );
